import{f as d,J as n,o as s,c as o,a6 as a,b as l,w as t,a as r,K as c,a7 as h}from"./chunks/framework.Dd1qhYRL.js";const _=JSON.parse('{"title":"Organizing SQL Files","description":"","frontmatter":{},"headers":[],"relativePath":"guide/sql-files/organization.md","filePath":"guide/sql-files/organization.md"}'),p={name:"guide/sql-files/organization.md"};function u(g,e,f,b,k,y){const i=n("Mermaid");return s(),o("div",null,[e[1]||(e[1]=a(`<h1 id="organizing-sql-files" tabindex="-1">Organizing SQL Files <a class="header-anchor" href="#organizing-sql-files" aria-label="Permalink to “Organizing SQL Files”">​</a></h1><p>Name your folders and files so the order they sort in is the order they run in.</p><p><code>noorm run build</code> finds every <code>.sql</code> and <code>.sql.tmpl</code> file under <code>paths.sql</code> (<code>./db/sql</code> after <code>noorm init</code>), sorts the paths as text, and runs them in that order. Every other file is ignored.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>db/sql/</span></span>
<span class="line"><span>├── 01_tables/</span></span>
<span class="line"><span>│   ├── 01_party.sql            # runs 1st</span></span>
<span class="line"><span>│   ├── 02_sales_order.sql      # 2nd</span></span>
<span class="line"><span>│   ├── 03_product.sql          # 3rd</span></span>
<span class="line"><span>│   ├── 04_order_line.sql       # 4th</span></span>
<span class="line"><span>│   └── 05_app_setting.sql      # 5th</span></span>
<span class="line"><span>├── 02_views/</span></span>
<span class="line"><span>│   └── 01_open_orders.sql      # 6th</span></span>
<span class="line"><span>├── 03_functions/</span></span>
<span class="line"><span>│   └── 01_place_order.sql      # 7th</span></span>
<span class="line"><span>├── 09_seeds/</span></span>
<span class="line"><span>│   ├── products.yml            # data file, never runs</span></span>
<span class="line"><span>│   ├── 01_products.sql.tmpl    # 8th</span></span>
<span class="line"><span>│   └── 02_gateway.sql.tmpl     # 9th</span></span>
<span class="line"><span>└── archive/                    # excluded in settings, never runs</span></span></code></pre></div><p><code>09_seeds</code> leaves <code>04</code> to <code>08</code> free for groups you add later, such as procedures and triggers.</p><h2 id="how-are-files-ordered" tabindex="-1">How are files ordered? <a class="header-anchor" href="#how-are-files-ordered" aria-label="Permalink to “How are files ordered?”">​</a></h2><p>noorm compares whole paths as text, one character at a time. The folder comes first in the path, so a folder prefix orders the folders and a file prefix orders the files inside one.</p><table tabindex="0"><thead><tr><th>Names, in the order you want</th><th>Run order</th><th>Why</th></tr></thead><tbody><tr><td><code>tables/</code>, <code>views/</code>, <code>functions/</code></td><td><code>functions/</code>, <code>tables/</code>, <code>views/</code></td><td><code>f</code> sorts before <code>t</code> before <code>v</code></td></tr><tr><td><code>2_party.sql</code>, <code>10_order.sql</code></td><td><code>10_order.sql</code>, <code>2_party.sql</code></td><td><code>1</code> sorts before <code>2</code> as text</td></tr><tr><td><code>accounts.sql</code>, <code>Users.sql</code></td><td><code>Users.sql</code>, <code>accounts.sql</code></td><td>every capital letter sorts before every lowercase one</td></tr></tbody></table><p>Pad the prefixes in a folder to one width: <code>01_</code> through <code>99_</code>, or <code>001_</code> past that. Name each file for the object it creates.</p><h2 id="which-files-take-part-in-a-build" tabindex="-1">Which files take part in a build? <a class="header-anchor" href="#which-files-take-part-in-a-build" aria-label="Permalink to “Which files take part in a build?”">​</a></h2><p>A file runs unless an exclude entry covers it, or an include list exists and does not cover it:</p>`,11)),(s(),l(h,null,{default:t(()=>[c(i,{id:"mermaid-78",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22db%2Fsql%2F%3Cbr%2F%3E.sql%20and%20.sql.tmpl%20files%22%5D%20--%3E%20B%7B%22under%20a%3Cbr%2F%3Ebuild.exclude%3Cbr%2F%3Eentry%3F%22%7D%0A%20%20%20%20B%20--%3E%7Cyes%7C%20X%5Bskipped%5D%0A%20%20%20%20B%20--%3E%7Cno%7C%20C%7B%22build.include%3Cbr%2F%3Eempty%3F%22%7D%0A%20%20%20%20C%20--%3E%7Cyes%7C%20R%5Bruns%5D%0A%20%20%20%20C%20--%3E%7Cno%7C%20D%7B%22under%20a%3Cbr%2F%3Ebuild.include%3Cbr%2F%3Eentry%3F%22%7D%0A%20%20%20%20D%20--%3E%7Cyes%7C%20R%0A%20%20%20%20D%20--%3E%7Cno%7C%20X%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<p>An entry is a folder or one file, relative to <code>paths.sql</code>. Both keys filter and neither reorders. <code>exclude</code> wins over <code>include</code>.</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .noorm/settings.yml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">build</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    exclude</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">archive</span></span></code></pre></div><h2 id="can-a-config-change-which-files-run" tabindex="-1">Can a config change which files run? <a class="header-anchor" href="#can-a-config-change-which-files-run" aria-label="Permalink to “Can a config change which files run?”">​</a></h2><p>A rule adds include or exclude entries when the active config matches. Rules run in order, every key in <code>match</code> must hold, and a later rule overrides an earlier one for the same entry.</p><p>Suppose test configs have no <code>PAYMENT_GATEWAY_KEY</code>. A template that reads a missing secret throws, so this rule keeps the gateway seed out of test builds:</p><div class="language-yaml"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># .noorm/settings.yml</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">description</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Test configs have no gateway key</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      match</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">          isTest</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      exclude</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">          - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">09_seeds/02_gateway.sql.tmpl</span></span></code></pre></div><table tabindex="0"><thead><tr><th><code>match</code> key</th><th>Holds when</th></tr></thead><tbody><tr><td><code>name</code></td><td>the config&#39;s name equals the value</td></tr><tr><td><code>isTest</code></td><td>the config&#39;s <code>isTest</code> flag equals the value</td></tr><tr><td><code>type</code></td><td>the config&#39;s type is <code>local</code> or <code>remote</code></td></tr><tr><td><code>protected</code></td><td><code>true</code> when the config&#39;s <code>user</code> role is below <code>admin</code></td></tr></tbody></table><p>Matching rules are merged into <code>build.include</code> and <code>build.exclude</code> before the build filters its files. <code>noorm run build --dry-run --config test</code> lists the files that config would run, and writes them rendered to <code>tmp/</code>.</p><h2 id="can-i-group-by-domain-instead-of-type" tabindex="-1">Can I group by domain instead of type? <a class="header-anchor" href="#can-i-group-by-domain-instead-of-type" aria-label="Permalink to “Can I group by domain instead of type?”">​</a></h2><p>Yes. Number the domain folders by dependency (<code>01_parties/</code>, <code>02_sales/</code>, <code>03_billing/</code>), and number <code>01_tables/</code> and <code>02_views/</code> inside each one. A view in <code>01_parties</code> runs before any <code>02_sales</code> table exists, so objects that reach across domains are easier to order by type.</p><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Mistake or symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>The build reports <code>success</code> with <code>filesRun=0</code>, or a file you excluded ran</td><td>An entry matched nothing. <code>sql/01_tables</code>, <code>./01_tables</code>, and <code>01_tables/</code> all match nothing, because entries start inside <code>paths.sql</code></td><td>Write <code>01_tables</code>. The build warns <code>Ignored 1 build.include entry that matched no files</code> and still exits <code>0</code>, so read the warnings in CI</td></tr><tr><td>A test build runs the seeds but creates no tables</td><td>A matching rule&#39;s <code>include</code> joins an empty <code>build.include</code>, so the list is no longer empty and only the rule&#39;s folders run</td><td>List every folder in <code>build.include</code>, and use rule <code>exclude</code> for the conditional part</td></tr><tr><td><code>run dir</code> runs a file that <code>build.exclude</code> lists</td><td>Only <code>run build</code> applies include, exclude, and rules</td><td>Name the files you want, or use <code>run build</code></td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/guide/sql-files/execution.html">Execution</a>: what a build skips, runs, and records</li><li><a href="/guide/sql-files/templates.html">Templates</a>: generate seeds from data files</li><li><a href="/getting-started/concepts.html">Concepts</a>: how <code>db/sql/</code> and <code>db/changes/</code> fit together</li><li><a href="/dev/settings.html">Settings reference</a>: every key in <code>settings.yml</code></li></ul>`,14))])}const E=d(p,[["render",u]]);export{_ as __pageData,E as default};
